package net.minecraft.nbt; import java.util.*; public class CompoundNBT { private final Map<String,Object> m=new HashMap<>(); public ListNBT getList(String k,int t){return (ListNBT)m.getOrDefault(k,new ListNBT());} public void put(String k,Object v){m.put(k,v);} public void putByte(String k, byte v){m.put(k,v);} public byte getByte(String k){Object v=m.get(k); return v instanceof Byte?(Byte)v:0;} }
